  root=root.toRealPath();String pkg=SourceCatalogueLedgerTest.PKG,repo=ConcordiaDemoScope.REPO,content="same Concordia immutable proposal\n",blob=EvidenceBundle.blob(content),head="a".repeat(40);Instant now=Instant.parse("2026-11-23T00:00:00Z");
