  var providerCalls=new java.util.concurrent.atomic.AtomicInteger();var settings=LlmSettings.fromEnvironment(Map.of("LLM_API_KEY","synthetic-offline"));byte[] response=SupplementalAssessmentTest.response("{\"verdicts\":[{\"id\":\"criterion\",\"verdict\":\"PASS\",\"rationale\":\"supported\",\"quotes\":[\"same Concordia immutable proposal\"]}]}");var supplemental=new SupplementalAssessment("Reviewer",settings,new LlmClient(settings,r->{providerCalls.incrementAndGet();try{String requestBody=new String(SupplementalAssessmentTest.body(r));var verdicts=Advisory.JSON.createObjectNode();var values=verdicts.putArray("verdicts");var seenIds=new HashSet<String>();for(int version:List.of(1,2)){String hash=RuleDocument.sha(Files.readAllBytes(Path.of("../rules/rule-v"+version+".json")));var doc=RuleDocument.runtime(new RuleDocument.Ref("rules/rule-v"+version+".json",null,hash));for(var clause:doc.clauses())if(requestBody.contains(clause.id())&&seenIds.add(clause.id())){var v=values.addObject().put("id",clause.id()).put("verdict","PASS").put("rationale","supported");v.putArray("quotes");if(!clause.kind().equals("PRESENCE_REQUIRED"))v.withArray("quotes").add("same Concordia immutable proposal");}}return SupplementalAssessmentTest.reply(200,SupplementalAssessmentTest.response(verdicts.toString()));}catch(Exception bad){throw new RuntimeException(bad);}},System::nanoTime,false),null,System.out,root.resolve("provider-cache"));var reviewer=new AgendaFollowingReview(evidence,supplemental);var idleGateway=new Reviewer.LedgerRuleGateway(){public List<Reviewer.EffectiveRule> activeRules(){throw new AssertionError("idle must not select fallback rule");}};assertEquals("IDLE",reviewer.cycle(idleGateway).path("status").asText());assertEquals(0,providerCalls.get());var v1=reviewer.cycle(gateway);assertTrue(v1.path("reviews").get(0).path("absence_eligible").asBoolean());assertTrue(v1.path("reviews").get(0).path("supplemental_assessment").path("exact").toString().contains("absent"));assertTrue(java.util.stream.StreamSupport.stream(v1.path("reviews").get(0).path("findings").spliterator(),false).anyMatch(f->f.path("clause_id").asText().equals("independent-security-audit")&&f.path("status").asText().equals("fail")));gateway.version=2;var v2=reviewer.cycle(gateway);assertEquals(v1.path("reviews").get(0).path("revision"),v2.path("reviews").get(0).path("revision"));assertEquals(2,v2.path("rule_version").asInt());assertFalse(v2.path("reviews").get(0).path("findings").isEmpty());assertEquals(RuleDocument.sha(Files.readAllBytes(Path.of("../rules/rule-v2.json"))),v2.path("reviews").get(0).path("rule_document_sha256").asText());assertEquals(2,calls.get());var cached=reviewer.cycle(gateway);assertEquals(IntegratedReviewOutput.identity(v2),IntegratedReviewOutput.identity(cached));assertEquals(2,providerCalls.get());
