  assertTrue(output.publish(v1,r->{}));var changed=v2.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)changed.path("reviews").get(0).path("findings").get(0)).put("status","changed-substantive-verdict");assertTrue(output.publish(changed,r->{}));
