 static ValueOuterClass.Value party(){return ValueOuterClass.Value.newBuilder().setParty("opener").build();}static ValueOuterClass.Value cid(String s){return ValueOuterClass.Value.newBuilder().setContractId(s).build();}static ValueOuterClass.Value none(){return ValueOuterClass.Value.newBuilder().setOptional(ValueOuterClass.Optional.getDefaultInstance()).build();}static ValueOuterClass.Value some(ValueOuterClass.Value v){return ValueOuterClass.Value.newBuilder().setOptional(ValueOuterClass.Optional.newBuilder().setValue(v)).build();}static EventOuterClass.CreatedEvent event(String id,ValueOuterClass.Value r){return EventOuterClass.CreatedEvent.newBuilder().setContractId(id).addSignatories("opener").addWitnessParties("opener").setCreateArguments(r.getRecord()).build();}
